];
export function initialConfig(): DashboardConfig {
  return {
    salt: 'pulse', counter: 8, aliases: {}, connections: [],
    items: widgetCatalog.slice(0, 8).map((w) => ({id: w.kind, type: 'pulse-widget', namespace: 'default', data: {kind: w.kind}})),
