.sidebar-label { font-size: 9px; font-weight: 600; letter-spacing: 1.05px; color: var(--g-color-text-secondary); padding: var(--g-spacing-7) var(--g-spacing-2) var(--g-spacing-2); }
.sidebar-footer { padding: var(--g-spacing-3); }
.sidebar-tip { padding: var(--g-spacing-4); background: var(--g-color-base-generic); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); margin-bottom: var(--g-spacing-5); }
.tip-icon { color: var(--g-color-text-brand); display: block; margin-bottom: var(--g-spacing-3); }
