.topbar-divider { height: 22px; width: 1px; background: var(--g-color-line-generic); }
.notification-button { position: relative; color: var(--g-color-text-secondary); }
.notification-button > i { position: absolute; right: 9px; top: 5px; width: 5px; height: 5px; border: 1px solid var(--g-color-base-background); border-radius: 50%; background: var(--g-color-base-brand); pointer-events: none; }
.dashboard-main { padding: var(--g-spacing-8); max-width: 1680px; margin: 0 auto; }
.page-heading { display: flex; justify-content: space-between; gap: var(--g-spacing-5); align-items: center; margin-bottom: var(--g-spacing-6); }
.title-line { display: flex; align-items: center; gap: var(--g-spacing-3); }
