    config.layout[0].y = 40;
    config.items.push({id: 'note-1', type: 'pulse-widget', namespace: 'default', data: {kind: 'note', text: 'Проверить продажи'}});
    config.layout.push({i: 'note-1', x: 0, y: 50, w: 4, h: 9});
